 window.history.pushState({}, "", path);
 document.title = title;
 }
 };

 // Create a proper encoded query for filtering
 const createFilterQuery = () => {
 if (selectedDate) {
 return `summary_date=${selectedDate}`;
 }
 return '';
 };

 return (
 <div style={{ padding: '20px' }}>
 <Card>
 <CardHeader label="Daily Leave Summary Reports" />

 <div style={{ padding: '16px', borderBottom: '1px solid #e0e0e0' }}>
 <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: '16px' }}>
 <Input
 label="Filter by Date"
 value={selectedDate}
 onValueSet={handleDateChange}
 type="date"
 />

 <Button
 label="Refresh"
 onClicked={handleRefresh}
 />
 </div>

 <div style={{ fontSize: '14px', color: '#666' }}>
 {selectedDate ? (
 `Showing leave records for: ${selectedDate}`
 ) : (
 'Please select a date to filter records'
 )}
 </div>
 </div>

 <NowRecordListConnected
 key={`${listKey}-${selectedDate || 'nodate'}`}
 table="x_1973840_leave_daily_leave_summary"
 listTitle={selectedDate ? `Leave Records for ${selectedDate}` : "Daily Leave Summary"}
 columns="employee_name,leave_start_date,leave_end_date,leave_start_time,leave_end_time,leave_reason,leave_type,approval_status"
 query={createFilterQuery()}
 limit={50}
 onRowClicked={(e: any) => navigateToView("details", e.detail.payload.sys_id, { title: "Leave Record Details" })}
 hideHeader={false}
 onNewActionClicked={() => navigateToView("original", undefined, { title: "View Original Records" })}
 />
 </Card>
 </div>
 );
